insert into public.exercises (name, category, muscle_groups, equipment, unilateral, instructions, coaching_cues) values
('Sentadilla goblet','fuerza',array['Cuádriceps','Glúteos','Core']::text[],array['Kettlebells','Mancuernas']::text[],false,'Sostené la pesa contra el pecho, pies al ancho de hombros. Bajá entre las piernas manteniendo el torso erguido y subí empujando el piso.','Rodillas en la línea de los pies. Pecho alto. Talones apoyados.'),
('Sentadilla trasera con barra','fuerza',array['Cuádriceps','Glúteos','Lumbares']::text[],array['Barra y discos','Rack']::text[],false,'Barra apoyada en la espalda alta. Bajá controlado hasta la profundidad que permita mantener la columna neutra y subí con fuerza.','Bracing antes de bajar. Rodillas hacia afuera. Columna neutra.'),
('Sentadilla frontal','fuerza',array['Cuádriceps','Glúteos','Core']::text[],array['Barra y discos','Rack']::text[],false,'Barra apoyada sobre los deltoides delanteros con codos altos. Bajá con el torso vertical y subí manteniendo los codos arriba.','Codos altos. Torso vertical. Respirar y bloquear el core.'),
('Sentadilla búlgara','fuerza',array['Cuádriceps','Glúteos','Aductores']::text[],array['Mancuernas','Banco']::text[],true,'Pie de atrás apoyado en un banco. Bajá la rodilla trasera hacia el piso con el peso en la pierna de adelante y subí.','Rodilla delantera estable. Tronco levemente inclinado. Bajar controlado.'),
('Zancada caminando','fuerza',array['Cuádriceps','Glúteos']::text[],array['Mancuernas','Solo peso corporal']::text[],true,'Da un paso largo, bajá hasta que ambas rodillas formen 90° y avanzá con la otra pierna.','Pasos largos. Rodilla alineada con el pie. Torso erguido.'),
('Zancada lateral','fuerza',array['Aductores','Glúteos','Cuádriceps']::text[],array['Mancuernas','Solo peso corporal']::text[],true,'Paso amplio hacia el costado, flexioná esa rodilla llevando la cadera atrás y volvé al centro empujando.','Pierna de apoyo extendida. Cadera atrás. Pie de trabajo apuntando adelante.'),
('Peso muerto rumano','fuerza',array['Isquiotibiales','Glúteos','Lumbares']::text[],array['Barra y discos','Mancuernas']::text[],false,'Con rodillas levemente flexionadas, llevá la cadera atrás deslizando la carga por los muslos hasta sentir tensión en isquios y volvé.','Bisagra de cadera. Espalda neutra. Carga pegada al cuerpo.'),
('Peso muerto rumano a una pierna','fuerza',array['Isquiotibiales','Glúteos','Core']::text[],array['Mancuernas','Kettlebells']::text[],true,'Sobre una pierna, inclinate llevando la otra pierna atrás en línea con el torso hasta que la cadera quede paralela al piso.','Cadera nivelada. Pierna de apoyo blanda. Movimiento lento.'),
('Peso muerto convencional','fuerza',array['Glúteos','Isquiotibiales','Lumbares','Espalda alta']::text[],array['Barra y discos']::text[],false,'Barra sobre el medio del pie. Agarrá, tensá la espalda y empujá el piso extendiendo rodillas y cadera a la vez.','Barra pegada. Espalda neutra. Terminar con glúteos, sin hiperextender.'),
('Peso muerto con barra hexagonal','fuerza',array['Cuádriceps','Glúteos','Isquiotibiales']::text[],array['Barra y discos']::text[],false,'Parado dentro de la barra hexagonal, agarrá las manijas y extendé piernas y cadera hasta quedar erguido.','Pecho alto. Empujar el piso. Bajar con control.'),
('Hip thrust','fuerza',array['Glúteos','Isquiotibiales']::text[],array['Barra y discos','Banco']::text[],false,'Espalda alta apoyada en un banco, barra sobre la cadera. Elevá la cadera hasta alinear tronco y muslos y bajá.','Mentón hacia el pecho. Pelvis en retroversión arriba. Pausa de 1 s.'),
('Puente de glúteo a una pierna','fuerza',array['Glúteos','Isquiotibiales']::text[],array['Solo peso corporal']::text[],true,'Acostado boca arriba, una pierna flexionada y la otra extendida. Elevá la cadera empujando con el talón.','Cadera nivelada. Empujar con el talón. Sin arquear la zona lumbar.'),
('Step-up al cajón','fuerza',array['Cuádriceps','Glúteos']::text[],array['Cajón pliométrico','Mancuernas']::text[],true,'Subí al cajón apoyando todo el pie y extendé la pierna sin impulsarte con la de abajo. Bajá controlado.','Empujar solo con la pierna de arriba. Rodilla estable. Bajada lenta.'),
('Curl nórdico','fuerza',array['Isquiotibiales']::text[],array['Solo peso corporal']::text[],false,'De rodillas con los tobillos sujetos, dejate caer hacia adelante lo más lento posible manteniendo cadera extendida.','Cadera extendida. Frenar con isquios. Usar las manos para amortiguar.'),
('Aducción en banco (Copenhague)','fuerza',array['Aductores','Core']::text[],array['Banco']::text[],true,'En plancha lateral con la pierna de arriba apoyada en el banco, elevá la cadera y sostené o repetí.','Cuerpo alineado. Cadera arriba. Empezar con la rodilla apoyada.'),
('Elevación de talones','fuerza',array['Pantorrillas']::text[],array['Mancuernas','Solo peso corporal']::text[],false,'Sobre un escalón, bajá los talones y subí lo más alto posible.','Recorrido completo. Pausa arriba. Bajada lenta.'),
('Press de banca con mancuernas','fuerza',array['Pectorales','Tríceps','Hombros']::text[],array['Mancuernas','Banco']::text[],false,'Acostado en el banco, bajá las mancuernas hasta la altura del pecho y empujá hacia arriba.','Escápulas juntas. Codos a 45°. Pies firmes.'),
('Press de banca','fuerza',array['Pectorales','Tríceps','Hombros']::text[],array['Barra y discos','Banco','Rack']::text[],false,'Bajá la barra al pecho medio de forma controlada y empujá hasta extender los codos.','Escápulas retraídas. Muñecas rectas. Barra en línea con los codos.'),
('Flexiones de brazos','fuerza',array['Pectorales','Tríceps','Core']::text[],array['Solo peso corporal']::text[],false,'En plancha con manos al ancho de hombros, bajá el pecho al piso y empujá.','Cuerpo en bloque. Codos a 45°. Rango completo.'),
('Remo con mancuerna a una mano','fuerza',array['Dorsales','Espalda alta','Bíceps']::text[],array['Mancuernas','Banco']::text[],true,'Con una mano y rodilla en el banco, llevá la mancuerna hacia la cadera y bajá controlado.','Espalda neutra. Tirar con el codo. Sin rotar el tronco.'),
('Remo invertido en suspensión','fuerza',array['Espalda alta','Dorsales','Bíceps']::text[],array['Suspensión (TRX)']::text[],false,'Colgado de las manijas con el cuerpo recto, llevá el pecho hacia las manos y bajá.','Cuerpo en bloque. Escápulas atrás. Más horizontal = más difícil.'),
('Dominadas','fuerza',array['Dorsales','Bíceps','Espalda alta']::text[],array['Solo peso corporal']::text[],false,'Colgado de la barra, subí hasta pasar el mentón y bajá hasta extender los brazos.','Arrancar desde las escápulas. Sin balanceo. Bajada controlada.'),
('Jalón al pecho','fuerza',array['Dorsales','Bíceps']::text[],array['Máquinas de gimnasio','Poleas']::text[],false,'Tirá de la barra hacia la parte alta del pecho con el torso levemente inclinado atrás.','Pecho alto. Codos hacia abajo. Sin tirar con el cuello.'),
('Press de hombros con mancuernas','fuerza',array['Hombros','Tríceps']::text[],array['Mancuernas']::text[],false,'De pie o sentado, empujá las mancuernas desde los hombros hasta arriba de la cabeza.','Core firme. Costillas abajo. Sin arquear la espalda.'),
('Press landmine a un brazo','fuerza',array['Hombros','Pectorales','Core']::text[],array['Barra y discos']::text[],true,'Con un extremo de la barra anclado, empujá el otro extremo hacia adelante y arriba con una mano.','Cadera y tronco estables. Empujar en diagonal. Escápula libre.'),
('Face pull','fuerza',array['Espalda alta','Manguito rotador','Hombros']::text[],array['Poleas','Bandas elásticas']::text[],false,'Tirá de la cuerda hacia la cara separando las manos y rotando los hombros hacia afuera.','Codos altos. Pulgares atrás. Pausa al final.'),
('Rotación externa de hombro con banda','activacion',array['Manguito rotador']::text[],array['Bandas elásticas']::text[],true,'Codo pegado al cuerpo a 90°, rotá el antebrazo hacia afuera contra la banda y volvé lento.','Codo fijo. Movimiento lento. Sin compensar con el tronco.'),
('Y-T-W en banco inclinado','activacion',array['Espalda alta','Manguito rotador']::text[],array['Mancuernas','Banco']::text[],false,'Boca abajo en banco inclinado, elevá los brazos formando Y, luego T y luego W con pesos livianos.','Escápulas abajo y atrás. Pulgares arriba. Peso liviano.'),
('Curl de muñeca y pronosupinación','fuerza',array['Antebrazos']::text[],array['Mancuernas']::text[],true,'Con el antebrazo apoyado, flexioná la muñeca y luego rotá la mancuerna tomada de un extremo.','Antebrazo fijo. Movimiento lento. Importante para el agarre del palo.'),
('Paseo del granjero','fuerza',array['Antebrazos','Core','Espalda alta']::text[],array['Mancuernas','Kettlebells']::text[],false,'Caminá con una pesa pesada en cada mano manteniendo el cuerpo erguido.','Hombros abajo. Pasos cortos. Tronco quieto.'),
('Paseo de maleta','core',array['Oblicuos','Core','Antebrazos']::text[],array['Mancuernas','Kettlebells']::text[],true,'Caminá con una pesa en una sola mano sin inclinarte hacia ningún lado.','Tronco vertical. Hombros nivelados. Respirar sin perder tensión.'),
('Lanzamiento rotacional de balón medicinal','potencia',array['Oblicuos','Cadera','Core']::text[],array['Balón medicinal']::text[],true,'De costado a la pared, cargá en la pierna de atrás y lanzá el balón rotando desde la cadera con máxima velocidad.','La cadera inicia. Brazos acompañan. Máxima intención en cada lanzamiento.'),
('Lanzamiento rotacional en posición de golf','potencia',array['Oblicuos','Cadera','Core']::text[],array['Balón medicinal']::text[],true,'En postura de address, hacé un backswing corto y lanzá el balón contra la pared imitando la secuencia del swing.','Secuencia cadera-tronco-brazos. Pies firmes. Recuperar entre repeticiones.'),
('Lanzamiento frontal de pecho con balón','potencia',array['Pectorales','Tríceps','Core']::text[],array['Balón medicinal']::text[],false,'Desde el pecho, lanzá el balón hacia adelante explosivamente extendiendo brazos y piernas.','Triple extensión. Máxima velocidad. Pocas repeticiones.'),
('Slam de balón medicinal','potencia',array['Dorsales','Core','Cuerpo completo']::text[],array['Balón medicinal']::text[],false,'Elevá el balón sobre la cabeza y lanzalo con fuerza contra el piso.','Extenderse arriba. Golpear con todo el cuerpo. Atrapar y repetir.'),
('Lanzamiento por encima de la cabeza hacia atrás','potencia',array['Glúteos','Lumbares','Cuerpo completo']::text[],array['Balón medicinal']::text[],false,'Con el balón entre las piernas, extendé cadera y lanzalo hacia atrás por encima de la cabeza.','Bisagra de cadera. Extensión explosiva. Espacio libre detrás.'),
('Salto al cajón','potencia',array['Cuádriceps','Glúteos','Pantorrillas']::text[],array['Cajón pliométrico']::text[],false,'Desde parado, saltá al cajón aterrizando suave con ambos pies. Bajá caminando.','Aterrizaje silencioso. Rodillas afuera. Altura moderada.'),
('Salto con contramovimiento','potencia',array['Cuádriceps','Glúteos','Pantorrillas']::text[],array['Solo peso corporal']::text[],false,'Bajá rápido a cuarto de sentadilla y saltá lo más alto posible. Aterrizá amortiguando.','Brazos acompañan. Máxima altura. Aterrizaje estable.'),
('Salto lateral (skater)','potencia',array['Glúteos','Aductores','Pantorrillas']::text[],array['Solo peso corporal']::text[],true,'Saltá lateralmente de una pierna a la otra y estabilizá cada aterrizaje.','Frenar en cada apoyo. Cadera atrás. Rodilla alineada.'),
('Swing con kettlebell','potencia',array['Glúteos','Isquiotibiales','Core']::text[],array['Kettlebells']::text[],false,'Con bisagra de cadera, balanceá la pesa entre las piernas y proyectala hasta la altura del pecho extendiendo la cadera.','La cadera hace el trabajo. Brazos relajados. Glúteos firmes arriba.'),
('Jump squat con carga liviana','potencia',array['Cuádriceps','Glúteos']::text[],array['Mancuernas']::text[],false,'Con mancuernas livianas, bajá a media sentadilla y saltá explosivamente.','Carga liviana. Máxima velocidad. Aterrizaje suave.'),
('Cargada de potencia con mancuerna','potencia',array['Cuerpo completo','Glúteos','Hombros']::text[],array['Mancuernas']::text[],true,'Desde la rodilla, extendé cadera explosivamente y recibí la mancuerna en el hombro.','Extensión de cadera. Codo rápido. Recepción con piernas flexionadas.'),
('Press de pecho explosivo en polea','potencia',array['Pectorales','Hombros','Core']::text[],array['Poleas']::text[],true,'En postura dividida, empujá el cable con una mano lo más rápido posible y volvé controlado.','Rápido al empujar. Lento al volver. Tronco quieto.'),
('Rotación explosiva con cable','potencia',array['Oblicuos','Cadera','Core']::text[],array['Poleas']::text[],true,'En postura atlética, rotá desde la cadera llevando el cable de atrás hacia adelante con máxima velocidad.','La cadera lidera. Brazos largos. Frenar al final.'),
('Swings de velocidad con palo liviano','velocidad',array['Cuerpo completo']::text[],array['Palo de golf']::text[],true,'Hacé swings completos a máxima velocidad con un palo o varilla liviana, alternando lado dominante y no dominante.','Máxima intención. Descanso completo entre series. Calidad sobre cantidad.'),
('Swings de velocidad lado no dominante','velocidad',array['Cuerpo completo']::text[],array['Palo de golf']::text[],true,'Swings a máxima velocidad desde el lado contrario para equilibrar y mejorar la velocidad general.','Misma intención que del lado hábil. Pocas repeticiones.'),
('Swings con palo invertido','velocidad',array['Cuerpo completo']::text[],array['Palo de golf']::text[],true,'Tomá el palo del lado de la cabeza y hacé swings rápidos buscando el sonido en la zona de impacto.','Sonido después de la bola. Relajar brazos. Rotación completa.'),
('Press Pallof','core',array['Core','Oblicuos']::text[],array['Poleas','Bandas elásticas']::text[],true,'De costado a la polea, llevá el agarre desde el pecho hacia adelante y resistí la rotación.','Cadera y hombros mirando adelante. Respirar. Pausa con brazos extendidos.'),
('Press Pallof en semi-arrodillado','core',array['Core','Oblicuos','Glúteos']::text[],array['Poleas','Bandas elásticas']::text[],true,'Con una rodilla apoyada, empujá el cable hacia adelante sin dejar que el tronco rote.','Glúteo de la pierna de atrás activo. Tronco quieto.'),
('Leñador con cable (alto a bajo)','core',array['Oblicuos','Core','Hombros']::text[],array['Poleas']::text[],true,'Desde arriba y al costado, llevá el cable en diagonal hacia la cadera contraria rotando el tronco.','Pies firmes. Rotación desde la torácica. Control en la vuelta.'),
('Leñador inverso (bajo a alto)','core',array['Oblicuos','Core','Glúteos']::text[],array['Poleas','Bandas elásticas']::text[],true,'Desde abajo y al costado, llevá el cable en diagonal hacia arriba transfiriendo el peso.','Empujar con la pierna de atrás. Brazos largos. Tronco firme.'),
('Plancha frontal','core',array['Core']::text[],array['Solo peso corporal']::text[],false,'Apoyado en antebrazos y puntas de pie, mantené el cuerpo recto el tiempo indicado.','Glúteos activos. Costillas abajo. Sin hundir la cadera.'),
('Plancha lateral','core',array['Oblicuos','Core','Glúteos']::text[],array['Solo peso corporal']::text[],true,'Apoyado en un antebrazo y el costado del pie, elevá la cadera y mantené.','Cuerpo alineado. Cadera alta. Hombro sobre el codo.'),
('Dead bug','core',array['Core']::text[],array['Solo peso corporal']::text[],false,'Boca arriba con brazos y piernas arriba, extendé brazo y pierna contrarios sin despegar la zona lumbar.','Lumbar pegada al piso. Exhalar al extender. Lento.'),
('Bird dog','core',array['Core','Glúteos','Lumbares']::text[],array['Solo peso corporal']::text[],false,'En cuadrupedia, extendé brazo y pierna contrarios manteniendo la espalda quieta.','Cadera nivelada. Alargar, no elevar. Pausa de 2 s.'),
('Rueda abdominal','core',array['Core','Dorsales']::text[],array['Solo peso corporal']::text[],false,'De rodillas, rodá hacia adelante lo más lejos posible sin arquear la espalda y volvé.','Pelvis en retroversión. Rango que puedas controlar.'),
('Rotación rusa con balón','core',array['Oblicuos','Core']::text[],array['Balón medicinal']::text[],false,'Sentado con el tronco inclinado, rotá llevando el balón de lado a lado.','Rotar el tronco, no solo los brazos. Espalda larga.'),
('Plancha con arrastre de pesa','core',array['Core','Oblicuos','Hombros']::text[],array['Kettlebells','Mancuernas']::text[],false,'En plancha alta, pasá una pesa de un lado al otro por debajo del cuerpo sin rotar la cadera.','Cadera quieta. Pies separados. Movimiento lento.'),
('Rotación torácica en cuadrupedia','movilidad',array['Columna torácica']::text[],array['Solo peso corporal']::text[],true,'En cuadrupedia con una mano detrás de la cabeza, rotá el tronco llevando el codo hacia el techo.','Cadera quieta sobre las rodillas. Seguir el codo con la mirada. Exhalar al rotar.'),
('Open book (libro abierto)','movilidad',array['Columna torácica','Pectorales']::text[],array['Solo peso corporal']::text[],true,'Acostado de lado con rodillas flexionadas, abrí el brazo de arriba hacia el otro lado siguiendo con la mirada.','Rodillas juntas y apoyadas. Respirar en la apertura.'),
('Rotación torácica sentado con palo','movilidad',array['Columna torácica']::text[],array['Palo de golf']::text[],false,'Sentado con el palo sobre los hombros, rotá a cada lado manteniendo la cadera fija.','Columna alta. Cadera quieta. Rango sin dolor.'),
('Rotación de cadera 90/90','movilidad',array['Cadera','Glúteos']::text[],array['Solo peso corporal']::text[],false,'Sentado con ambas piernas a 90°, rotá las rodillas de un lado al otro sin usar las manos si es posible.','Torso alto. Movimiento lento. Pausa en cada lado.'),
('Rotación interna de cadera en cuadrupedia','movilidad',array['Cadera']::text[],array['Solo peso corporal']::text[],true,'En cuadrupedia, llevá el pie hacia afuera manteniendo la rodilla en el lugar.','Pelvis quieta. Rango controlado. Clave para el apoyo en el downswing.'),
('Estiramiento del flexor de cadera','movilidad',array['Cadera','Cuádriceps']::text[],array['Solo peso corporal']::text[],true,'En posición de caballero, llevá la pelvis hacia adelante con el glúteo de atrás activo.','Retroversión de pelvis. Glúteo activo. Sin arquear la lumbar.'),
('World''s greatest stretch','movilidad',array['Cadera','Columna torácica','Isquiotibiales']::text[],array['Solo peso corporal']::text[],true,'Desde zancada profunda, apoyá la mano, llevá el codo hacia el pie y rotá abriendo el brazo al techo.','Pierna de atrás extendida. Rotar desde el pecho. Respirar.'),
('Movilidad de tobillo en pared','movilidad',array['Tobillo','Pantorrillas']::text[],array['Solo peso corporal']::text[],true,'Frente a la pared, llevá la rodilla hacia adelante sin despegar el talón.','Talón apoyado. Rodilla sobre el segundo dedo. Ir y volver.'),
('Rotación con palo en postura de golf','movilidad',array['Columna torácica','Cadera']::text[],array['Palo de golf']::text[],false,'En postura de address con el palo cruzado en el pecho, rotá a cada lado manteniendo el ángulo de inclinación.','Mantener la inclinación. Rotar alrededor de la columna. Sin balanceo lateral.'),
('Disociación de cadera y tronco','movilidad',array['Cadera','Columna torácica','Core']::text[],array['Palo de golf']::text[],false,'En postura de golf, rotá la pelvis manteniendo el tronco quieto y luego al revés.','Un segmento por vez. Movimiento lento. Clave para la secuencia del swing.'),
('Gato-camello','movilidad',array['Columna torácica','Lumbares']::text[],array['Solo peso corporal']::text[],false,'En cuadrupedia, alterná flexión y extensión de toda la columna de forma lenta.','Segmentar la columna. Respirar con el movimiento.'),
('Estiramiento de dorsal en banco','movilidad',array['Dorsales','Columna torácica']::text[],array['Banco','Palo de golf']::text[],false,'De rodillas con los codos apoyados en el banco, dejá caer el pecho hacia el piso.','Codos juntos. Costillas abajo. Respirar profundo.'),
('Sentadilla profunda con apertura','movilidad',array['Cadera','Aductores','Tobillo']::text[],array['Solo peso corporal']::text[],false,'En sentadilla profunda, empujá las rodillas con los codos y alterná elevar un brazo rotando.','Talones apoyados. Pecho alto. Respirar abajo.'),
('Movilidad de hombro con palo (dislocaciones)','movilidad',array['Hombros','Pectorales']::text[],array['Palo de golf','Bandas elásticas']::text[],false,'Con agarre amplio, pasá el palo o banda desde adelante hasta atrás por encima de la cabeza.','Brazos extendidos. Agarre amplio al empezar. Sin dolor.'),
('Equilibrio a una pierna con alcance','estabilidad',array['Tobillo','Glúteos','Core']::text[],array['Solo peso corporal']::text[],true,'Sobre una pierna, alcanzá con el otro pie hacia adelante, al costado y atrás sin perder el equilibrio.','Rodilla estable. Cadera nivelada. Movimiento lento.'),
('Postura de golf a una pierna','estabilidad',array['Tobillo','Glúteos','Core']::text[],array['Palo de golf']::text[],true,'En postura de address, levantá un pie y mantené el equilibrio; avanzá a rotaciones lentas.','Mantener la inclinación. Peso en el medio del pie.'),
('Sentadilla a una pierna al cajón','estabilidad',array['Cuádriceps','Glúteos']::text[],array['Cajón pliométrico']::text[],true,'Sobre una pierna, sentate lentamente en el cajón y levantate sin impulso.','Rodilla alineada. Bajada de 3 s. Brazos adelante para equilibrar.'),
('Caminata lateral con banda','activacion',array['Glúteos','Cadera']::text[],array['Bandas elásticas']::text[],false,'Con una banda en las rodillas o tobillos, caminá de costado en media sentadilla.','Pasos cortos. Tensión constante. Pies apuntando adelante.'),
('Almeja con banda','activacion',array['Glúteos','Cadera']::text[],array['Bandas elásticas']::text[],true,'Acostado de lado con rodillas flexionadas, abrí la rodilla de arriba sin rotar la pelvis.','Pelvis quieta. Pausa arriba. Movimiento lento.'),
('Extensión de cadera en cuadrupedia','activacion',array['Glúteos']::text[],array['Bandas elásticas','Solo peso corporal']::text[],true,'En cuadrupedia, extendé una pierna hacia atrás y arriba usando el glúteo.','Sin arquear la lumbar. Rodilla a 90°. Pausa arriba.'),
('Activación escapular en pared','activacion',array['Espalda alta','Hombros']::text[],array['Solo peso corporal']::text[],false,'Con antebrazos en la pared, deslizalos hacia arriba manteniendo las escápulas abajo.','Costillas abajo. Escápulas abajo y afuera. Lento.'),
('Respiración 90/90 con globo o inflado','activacion',array['Core']::text[],array['Solo peso corporal']::text[],false,'Boca arriba con pies en la pared a 90°, inhalá por la nariz y exhalá largo activando el abdomen.','Costillas abajo. Exhalación larga. Lumbar apoyada.'),
